import Redis from 'ioredis';
import { getEnv } from '../config/env';

/**
 * Подключение к общему счётчику ограничения частоты.
 *
 * Зачем вообще: счётчики в памяти процесса — это не ограничение частоты, а его
 * видимость. Два экземпляра ядра считают свои запросы независимо, то есть
 * фактически разрешённая частота умножается на их число, а перезапуск обнуляет
 * счётчики целиком (SEC-11). Общий счётчик убирает и то, и другое.
 *
 * Клиент создаётся ДО поднятия Nest-приложения, потому что нужен при
 * регистрации плагина периметра, а не как обычная зависимость модуля.
 *
 * Что здесь принципиально:
 *  - **таймаут команды.** Зависший счётчик не должен держать запрос
 *    пользователя (RULES §3.1: таймаут на каждый внешний вызов);
 *  - **TLS в production** — проверяется конфигурацией, а здесь включается
 *    проверка цепочки: `rediss://` без валидации сертификата смысла не имеет;
 *  - **ограниченные повторы.** Бесконечная очередь команд при недоступном
 *    счётчике превращает деградацию в зависание.
 */
export function createRateLimitRedis(): Redis | null {
  const env = getEnv();
  if (!env.REDIS_URL) return null;

  return new Redis(env.REDIS_URL, {
    // Пароль передаётся параметром, а не частью адреса: внутри URL он попадает
    // в логи подключения и в тексты ошибок как есть.
    ...(env.REDIS_PASSWORD ? { password: env.REDIS_PASSWORD } : {}),
    // Плагин ограничения частоты обязан отвечать быстро или не отвечать вовсе.
    commandTimeout: env.REDIS_COMMAND_TIMEOUT_MS,
    connectTimeout: 5_000,
    // Команды, накопленные во время обрыва, отбрасываются: смысла применять их
    // через минуту нет, а очередь растёт неограниченно.
    enableOfflineQueue: false,
    // Команда, ушедшая до обрыва, имеет НЕИЗВЕСТНЫЙ результат: увеличение
    // могло выполниться. Повторная отправка после переподключения посчитала бы
    // запрос дважды, поэтому её нет — вызывающий получает отказ и решает сам.
    maxRetriesPerRequest: 0,
    autoResendUnfulfilledCommands: false,
    retryStrategy: (attempt) => Math.min(attempt * 200, 2_000),
    // Проверка сертификата включена явно: отключать её запрещено где угодно,
    // включая dev (RULES §4).
    tls: env.REDIS_URL.startsWith('rediss://') ? { rejectUnauthorized: true } : undefined,
  });
}
